question.answer:
from collections.abc import Callable


def shout(text: str) -> str:
    return text.upper() + "!"


def quiet(text: str) -> str:
    return text.lower() + "."


def apply_twice(transform: Callable[[str], str], text: str) -> str:
    return transform(transform(text))


def pick_transform(loud: bool) -> Callable[[str], str]:
    return shout if loud else quiet


def by_length(words: list[str]) -> list[str]:
    return sorted(words, key=len)

from collections.abc import Callable
from operator import itemgetter


def add(a: float, b: float) -> float:
    return a + b


def subtract(a: float, b: float) -> float:
    return a - b


def multiply(a: float, b: float) -> float:
    return a * b


def divide(a: float, b: float) -> float:
    return a / b


def floor_divide(a: float, b: float) -> float:
    return a // b


def modulo(a: float, b: float) -> float:
    return a % b


OPS: dict[str, Callable[[float, float], float]] = {
    "add": add,
    "sub": subtract,
    "mul": multiply,
    "div": divide,
    "floordiv": floor_divide,
    "mod": modulo,
}


def run(op: str, a: float, b: float) -> float | str:
    handler = OPS.get(op, lambda x, y: f"unknown operation {op!r}")
    return handler(a, b)


def by_severity(faults: list[dict[str, str | int]]) -> list[dict[str, str | int]]:
    return sorted(faults, key=lambda fault: (-fault["severity"], fault["name"]))


def worst(faults: list[dict[str, str | int]]) -> dict[str, str | int]:
    return max(faults, key=itemgetter("severity"))

