question.answer:
from collections.abc import Callable


# Supplied. Do not change these two.
def unbound_demo():
    total = 0

    def bump():
        total += 1
        return total

    try:
        return bump()
    except UnboundLocalError as exc:
        return type(exc).__name__


def broken_checkers(limits):
    checkers = []
    for limit in limits:
        checkers.append(lambda reading: reading > limit)
    return checkers


def make_counter() -> Callable[[], int]:
    count = 0

    def tick() -> int:
        nonlocal count
        count += 1
        return count

    return tick


def make_checker(limit: int) -> Callable[[int], bool]:
    def check(reading: int) -> bool:
        return reading > limit

    return check


def fixed_checkers(limits: list[int]) -> list[Callable[[int], bool]]:
    return [make_checker(limit) for limit in limits]
